"""Per-key token bucket replayed over a timeline of events. See task.md."""

from __future__ import annotations

from fractions import Fraction
from typing import NamedTuple


class ConfigError(ValueError):
    """Raised for an unusable config and for an unusable event stream."""


class Event(NamedTuple):
    timestamp_ms: int
    key: str
    cost: int


class Decision(NamedTuple):
    allowed: bool
    remaining: int
    retry_after_ms: int


def decide(config: dict, events: list[Event]) -> list[Decision]:
    """Replay `events` through a per-key token bucket, one Decision each."""
    for required in ("capacity", "refill_tokens", "refill_interval_ms"):
        if required not in config:
            raise ConfigError(f"missing required config key: {required}")

    capacity = config["capacity"]
    refill_tokens = config["refill_tokens"]
    refill_interval_ms = config["refill_interval_ms"]

    if capacity < 1:
        raise ConfigError("capacity must be at least 1")
    if refill_tokens < 1:
        raise ConfigError("refill_tokens must be at least 1")
    if refill_interval_ms < 1:
        raise ConfigError("refill_interval_ms must be at least 1")

    initial_tokens = config.get("initial_tokens", capacity)
    if initial_tokens < 0 or initial_tokens > capacity:
        raise ConfigError("initial_tokens must be between 0 and capacity")

    rate = Fraction(refill_tokens, refill_interval_ms)

    buckets: dict[str, Fraction] = {}
    last_t: dict[str, int] = {}
    last_timestamp: int | None = None

    decisions: list[Decision] = []

    for event in events:
        t, key, cost = event.timestamp_ms, event.key, event.cost

        if cost < 0:
            raise ConfigError("event cost must not be negative")
        if last_timestamp is not None and t < last_timestamp:
            raise ConfigError("events must be sorted by timestamp")
        last_timestamp = t

        if key not in buckets:
            tokens = Fraction(initial_tokens)
        else:
            elapsed = t - last_t[key]
            tokens = buckets[key] + elapsed * rate
            if tokens > capacity:
                tokens = Fraction(capacity)

        if cost > capacity:
            allowed = False
            retry_after_ms = -1
        elif tokens >= cost:
            allowed = True
            retry_after_ms = 0
            tokens -= cost
        else:
            allowed = False
            deficit = Fraction(cost) - tokens
            wait = deficit / rate
            wait_ms = -(-wait.numerator // wait.denominator)
            retry_after_ms = wait_ms

        buckets[key] = tokens
        last_t[key] = t

        remaining = tokens.numerator // tokens.denominator
        decisions.append(Decision(allowed, remaining, retry_after_ms))

    return decisions
